# Agente Semillas: cada corrida (cron */2) busca docs/_task.py en el repo; si cambió, lo ejecuta.
# La tarea escribe su propio resultado a docs/_diag.json. Escribir _task.py requiere el token (repo write-protected).
import os,re,json,base64,hashlib,subprocess,urllib.request,time
B="/home/opc/bot_semillas"
def get_tok():
    try:
        for L in open(B+"/.env"):
            m=re.search(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+)",L)
            if m: return m.group(1)
    except Exception: pass
    return ""
T=get_tok()
if not T: raise SystemExit(0)
url="https://api.github.com/repos/calcagnoagustin/radar/contents/docs/_task.py?ref=main"
req=urllib.request.Request(url)
req.add_header("Authorization","token "+T); req.add_header("User-Agent","semillas-agent")
try:
    d=json.loads(urllib.request.urlopen(req,timeout=30).read())
    content=base64.b64decode(d["content"])
except Exception:
    raise SystemExit(0)
h=hashlib.sha256(content).hexdigest()
ST=B+"/.agent_last"
last=open(ST).read().strip() if os.path.exists(ST) else ""
if h==last: raise SystemExit(0)
open(ST,"w").write(h)
tf=B+"/.agent_task.py"
open(tf,"wb").write(content)
try:
    subprocess.run([B+"/venv/bin/python",tf],timeout=180)
    print("ran",h[:8],time.strftime("%H:%M:%SZ",time.gmtime()))
except Exception as e:
    print("task_err",e)
